table.matrix th, table.matrix td {
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 0.4rem 0.55rem;
  text-align: center;
  background: var(--surface);
  white-space: nowrap;
}
table.matrix thead th {
  position: sticky;
  top: 0;
  z-index: 5;
  color: var(--muted);
  font-weight: 600;
  cursor: pointer;
  user-select: none;
}
table.matrix thead th:hover { color: var(--accent); }
table.matrix tfoot th, table.matrix tfoot td {
  position: sticky;
  bottom: 0;
  z-index: 5;
  font-weight: 700;
  background: color-mix(in srgb, var(--surface) 78%, black);
}
table.matrix tbody th {
  text-align: left;
  white-space: normal;
  max-width: 22rem;
  vertical-align: top;
}
table.matrix .sticky-col {
  position: sticky;
  left: 0;
  z-index: 3;
  background: color-mix(in srgb, var(--surface) 96%, black);
}
table.matrix .sticky-col-right {
  position: sticky;
  right: 0;
  z-index: 3;
  background: color-mix(in srgb, var(--surface) 96%, black);
}
/* Must out-specificity table.matrix .sticky-col(-right) (2 classes)
   and table.matrix thead/tfoot th (3 type selectors) — a bare .corner
   class loses to both and lets scrolling cells paint over the pinned
   corner. */
table.matrix th.corner, table.matrix td.corner { z-index: 9; }
th[data-sort-key].sort-asc::after { content: " \25B2"; }
th[data-sort-key].sort-desc::after { content: " \25BC"; }
.status-dot {
  display: inline-block;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  margin-right: 0.35rem;
}
.status-dot.status-proposed { background: var(--coupled); }
.status-dot.status-actual { background: var(--accent); }
.status-dot.status-deprecated { background: var(--warn); }
.status-dot.status-other { background: var(--muted); }
.force-accordion-toggle {
  background: transparent;
  border: none;
  color: var(--coupled);
  font: 600 13px var(--mono);
  cursor: pointer;
  padding: 0;
}
.force-detail {
  margin-top: 0.4rem;
  font: 12px/1.4 var(--sans);
  color: var(--muted);
}
.force-detail dl { margin: 0; }
.force-detail dt {
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 0.65rem;
  color: var(--accent);
  margin-top: 0.35rem;
}
.force-detail dd { margin: 0; }
table.matrix tbody tr.force-row[hidden] { display: none; }
[data-residue-cell][data-coupled="1"] {
  background: color-mix(in srgb, var(--coupled) 28%, transparent);
  color: var(--coupled);
  font-weight: 700;
}
th[data-fission="1"], td[data-fission="1"] {
  outline: 2px solid var(--warn);
  outline-offset: -2px;
}
th[data-fusion="1"], td[data-fusion="1"] {
  outline: 2px solid var(--coupled);
  outline-offset: -2px;
}
.generators {
  display: grid;
  gap: 0.85rem;

