110:-      function shellQuote(value) {
111:-        const s = String(value == null ? "" : value);
112:-        if (s.indexOf("\n") !== -1 || s.indexOf("\r") !== -1) {
113:-          let escaped = "";
114:-          for (const ch of s) {
115:-            if (ch === "\\") escaped += "\\\\";
116:-            else if (ch === "'") escaped += "\\'";
117:-            else if (ch === "\n") escaped += "\\n";
118:-            else if (ch === "\r") escaped += "\\r";
119:-            else if (ch === "\t") escaped += "\\t";
120:-            else escaped += ch;
121:-          }
122:-          return "$'" + escaped + "'";
123:-        }
124:-        return "'" + s.replace(/'/g, "'\\''") + "'";
125:-      }
126:-
127:-      function pushFlag(parts, flag, value) {
128:-        parts.push(flag + " " + shellQuote(value));
129:-      }
130:-
131:-      function pushOptionalFlag(parts, flag, value) {
132:-        if (value != null && String(value) !== "") pushFlag(parts, flag, value);
133:-      }
134:-
135:-      function buildAddCommand(target, fields) {
136:-        const f = fields || {};
137:-        const parts = ["residual add " + target];
138:-        switch (target) {
139:-          case "stressor":
140:-          case "purpose":
141:-          case "meta-purpose":
142:-            pushFlag(parts, "--description", f.description || "");
143:-            pushFlag(parts, "--attractor-id", f.attractor_id || "");
144:-            pushFlag(parts, "--naive-change", f.naive_change || "");
145:-            pushOptionalFlag(parts, "--shortname", f.shortname || "");
146:-            pushOptionalFlag(parts, "--outcomes", f.outcomes || "");
147:-            break;
148:-          case "attractor":
149:-          case "meta-attractor":
150:-            pushFlag(parts, "--name", f.name || "");
151:-            pushFlag(parts, "--description", f.description || "");
152:-            pushFlag(parts, "--positive-state", f.positive_state || "");
153:-            pushFlag(parts, "--negative-state", f.negative_state || "");
154:-            break;
155:-          case "component":
156:-            pushFlag(parts, "--name", f.name || "");
157:-            pushFlag(parts, "--description", f.description || "");
158:-            pushFlag(parts, "--status", f.status || "");
159:-            pushFlag(parts, "--architecture-set", f.architecture_set || "");
160:-            break;
161:-          case "meta-stressor":
162:-            pushFlag(parts, "--description", f.description || "");
163:-            pushOptionalFlag(parts, "--shortname", f.shortname || "");
164:-            break;
165:-          case "defense-persona":
166:-          case "defense-strategy":
167:-          case "defense-progress":
168:-          case "defense-pitch":
169:-            pushFlag(parts, "--name", f.name || "");
170:-            pushFlag(parts, "--body", f.body || "");
171:-            break;
172:-          default:
173:-            throw new Error("unknown add target: " + target);
174:-        }
175:-        return parts.join(" ");
176:-      }
177:-
178:-      function formFields(form) {
179:-        const data = {};
180:-        for (const el of form.querySelectorAll("input, textarea, select")) {
181:-          if (!el.name) continue;
182:-          data[el.name] = el.value;
183:-        }
184:-        return data;
185:-      }
186:-
187:-      function appendStaged(command) {
188:-        const box = document.getElementById("staged-commands");
189:-        box.value = box.value ? box.value + "\n" + command : command;
190:-      }
191:-
192:-      document.querySelectorAll("form[data-command-generator]").forEach((form) => {
193:-        form.addEventListener("submit", (ev) => {
194:-          ev.preventDefault();
195:-          const target = form.getAttribute("data-command-generator");
196:-          appendStaged(buildAddCommand(target, formFields(form)));
197:-        });
198:-      });
199:-
200:-      const filterInput = document.querySelector("[data-force-filter]");
201:-      if (filterInput) {
202:-        filterInput.addEventListener("input", () => {
203:-          const q = filterInput.value.trim().toLowerCase();
204:-          document.querySelectorAll("table.matrix tbody tr.force-row").forEach((row) => {
205:-            const hay = (row.getAttribute("data-search") || row.textContent || "").toLowerCase();
206:-            row.hidden = q !== "" && hay.indexOf(q) === -1;
207:-          });
208:-        });
209:-      }
210:-
211:-      document.querySelectorAll("[data-accordion-toggle]").forEach((btn) => {
212:-        btn.addEventListener("click", () => {
213:-          const detail = btn.nextElementSibling;
214:-          if (!detail) return;
215:-          const expanded = btn.getAttribute("aria-expanded") === "true";
216:-          btn.setAttribute("aria-expanded", String(!expanded));
217:-          detail.hidden = expanded;
