219:-      });
220:-
221:-      function sortMatrixBy(key, dir) {
222:-        const table = document.querySelector("table.matrix");
223:-        const tbody = table && table.querySelector("tbody");
224:-        if (!tbody) return;
225:-        const rows = Array.from(tbody.querySelectorAll("tr.force-row"));
226:-        const mult = dir === "desc" ? -1 : 1;
227:-        rows.sort((ra, rb) => {
